  ts: {
    name: "TypeScript", tagline: "JS with types and safety", emoji: "🟦",
    levels: {
      beginner: [
        { id: "ts-beginner-what", title: "What is TypeScript?", topic: "A typed superset of JavaScript that compiles to plain JS.", learn: "You'll understand why types prevent whole classes of bugs.", theory: "TypeScript adds static types on top of JavaScript. Your editor can catch mistakes before you even run the code.", example: "// before (JS)\nlet n = 5;\nn = 'hello'; // allowed, causes bugs\n\n// after (TS)\nlet n: number = 5;\nn = 'hello'; // ❌ type error caught now", quiz: { question: "What does TypeScript add to JavaScript?", options: ["Runtime speed", "Static type checking", "A new browser", "CSS styling"], answer: "B", explain: "TypeScript's core value is compile-time type checking.", retryExplain: "It catches type mistakes before the code runs." } },
        { id: "ts-beginner-types", title: "Basic types", topic: "number, string, boolean, arrays, and object shapes.", learn: "You'll annotate variables and functions with types.", theory: "TS has number, string, boolean, and array types. Function parameters and returns can be typed too.", example: "function greet(name: string, times: number): string {\n  return name.repeat(times);\n}", quiz: { question: "Which is a valid TS type annotation?", options: ["let x: num", "let x: number", "let x: int", "let x: digit"], answer: "B", explain: "number is the TS type for numeric values.", retryExplain: "The type keyword is 'number'." }, exercise: { lang: "ts", prompt: "Write a typed function that adds two numbers and returns a number.", expected: "" } },
        { id: "ts-beginner-functions", title: "Typed functions", topic: "parameter types, return types, and optional params.", learn: "You'll write functions with explicit contracts.", theory: "You type each parameter and the return value, and mark optionals with ?.", example: "function divide(a: number, b: number, precision?: number): number {\n  const r = a / b;\n  return precision ? Number(r.toFixed(precision)) : r;\n}", quiz: { question: "How do you make a parameter optional in TS?", options: ["param: type = 0", "param?: type", "param*: type", "optional param: type"], answer: "B", explain: "The ? suffix marks a parameter as optional.", retryExplain: "A ? after the name makes it optional." } },
        { id: "ts-beginner-interfaces", title: "Interfaces", topic: "shaping objects with interfaces.", learn: "You'll define reusable object contracts.", theory: "An interface describes the shape an object must have. It's a contract your code and others rely on.", example: "interface User { id: number; name: string; email?: string; }\nfunction saveUser(u: User) { /* ... */ }", quiz: { question: "What does an interface define?", options: ["A function body", "An object's shape", "A CSS class", "A database"], answer: "B", explain: "Interfaces define the shape/structure of objects.", retryExplain: "Interfaces describe object shapes." } },
        { id: "ts-beginner-union", title: "Union types", topic: "a value that can be one of several types.", learn: "You'll express flexible inputs safely.", theory: "A union type uses | to allow one of several types. Narrowing with typeof checks keeps your code safe.", example: "function format(id: number | string) {\n  if (typeof id === 'number') return id.toFixed(2);\n  return id.toUpperCase();\n}", quiz: { question: "Which is a valid union type?", options: ["number and string", "number | string", "number: string", "number + string"], answer: "B", explain: "The | operator creates a union.", retryExplain: "Use | between types for a union." } },
      ],
      intermediate: [
        { id: "ts-int-generics", title: "Generics", topic: "type-safe reusable functions and classes.", learn: "You'll write functions that work with any type safely.", theory: "Generics let a function work with many types while keeping type safety, using a type parameter <T>.", example: "function first<T>(arr: T[]): T | undefined {\n  return arr[0];\n}\nconst n = first([1, 2, 3]); // n: number", quiz: { question: "What does a generic <T> do?", options: ["Makes a function private", "Captures the caller's type", "Adds a template literal", "Disables types"], answer: "B", explain: "<T> captures whatever type the caller uses.", retryExplain: "The type parameter T is inferred from usage." } },
        { id: "ts-int-narrowing", title: "Type narrowing", topic: "discriminated unions and type guards.", learn: "You'll write code that narrows types safely.", theory: "Narrowing shrinks a union to one type inside a branch, using typeof, in, or custom type guards.", example: "type Shape = { kind: 'circle'; r: number } | { kind: 'square'; side: number };\nfunction area(s: Shape) {\n  if (s.kind === 'circle') return Math.PI * s.r ** 2;\n  return s.side ** 2;\n}", quiz: { question: "What is a discriminated union?", options: ["Two functions", "Objects with a shared literal 'kind' field", "A union of numbers", "A CSS grid"], answer: "B", explain: "A shared literal discriminant field lets you narrow precisely.", retryExplain: "A common 'kind' literal field acts as the discriminator." } },
        { id: "ts-int-keyof", title: "keyof and indexed access", topic: "working with object keys as types.", learn: "You'll build type-safe key access.", theory: "keyof T gives you the union of T's keys. Indexed access T[K] gives the type of a property.", example: "interface Config { url: string; retries: number }\ntype Key = keyof Config; // 'url' | 'retries'\nfunction get<T, K extends keyof T>(o: T, k: K): T[K] {\n  return o[k];\n}", quiz: { question: "What does keyof Config return?", options: ["A number", "The keys of Config as a union", "A string", "An array"], answer: "B", explain: "keyof yields a union of the interface's keys.", retryExplain: "keyof produces the union of property names." } },
      ],
      advanced: [
        { id: "ts-adv-mapped", title: "Mapped & conditional types", topic: "transform types and compute types conditionally.", learn: "You'll build advanced reusable types.", theory: "Mapped types iterate over keys; conditional types pick a type based on a condition with extends.", example: "type Readonly<T> = { readonly [K in keyof T]: T[K] };\ntype IsString<T> = T extends string ? true : false;", quiz: { question: "What does a mapped type do?", options: ["Deletes types", "Transforms each property's type", "Adds runtime code", "Renames variables"], answer: "B", explain: "Mapped types transform every property of a type.", retryExplain: "It maps over keys to transform each property." } },
        { id: "ts-adv-declare", title: "Declaration files", topic: ".d.ts and typing untyped modules.", learn: "You'll type third-party JS code.", theory: "Declaration files end in .d.ts and describe the types of JS without implementations, letting TS understand untyped libraries.", example: "// my-lib.d.ts\ndeclare module 'my-lib' {\n  export function doThing(x: number): string;\n}", quiz: { question: "What file extension do declaration files use?", options: [".ts", ".d.ts", ".js", ".types"], answer: "B", explain: "Declaration files use the .d.ts extension.", retryExplain: "It's .d.ts — describe, no implementation." } },
      ],
      pro: [
        { id: "ts-pro-typelevel", title: "Type-level programming", topic: "computations performed entirely in the type system.", learn: "You'll write powerful conditional/mapped type utilities.", theory: "Advanced TS lets you do logic at the type level — unions, infer, recursion — producing types that enforce invariants.", example: "type Unwrap<T> = T extends Array<infer U> ? U : T;\nconst a: Unwrap<number[]> = 5; // number", quiz: { question: "What does infer do in conditional types?", options: ["Deletes types", "Captures a type from a match", "Adds generics", "Disables checks"], answer: "B", explain: "infer captures a type from within a conditional match.", retryExplain: "infer pulls a type out of a pattern." } },
      ],
    },
  },

